function render(){document.getElementById('medList').innerHTML=meds.map((m,i)=>`<div class="card med"><div class="ey">${m[0]}</div><h2>${m[1]}</h2><span class="badge">${m[2]}</span><p><b>Target:</b> ${m[3]}</p><p><b>Path:</b> ${m[4]}</p><div class="call"><b>Benefit</b><br>${m[5]}</div><div class="call danger" style="margin-top:8px"><b>Collateral burden</b><br>${m[6]}</div><div class="call" style="margin-top:8px"><b>ILMB same-goal route</b><br>${m[7]}</div><p class="small muted"><b>Common output:</b> ${m[8]}</p><span class="badge ${m[9].includes('GAP')?'bad':'watch'}">${m[9]}</span><label>What I actually experience</label><textarea data-med="${i}">${state.notes['med'+i]||''}</textarea></div>`).join('');document.getElementById('labRows').innerHTML=labs.map(l=>`<tr><td><b>${l[1]}</b><br><span class="badge ${l[6]}">${l[6]}</span></td><td>${l[2]} ${l[3]}</td><td>${l[4]||'—'}</td><td>${l[5]}</td><td><input type="number" step="any" data-lab="${l[0]}" value="${state.labs[l[0]]?.value||''}"></td><td><input type="date" data-labdate="${l[0]}" value="${state.labs[l[0]]?.date||''}"></td><td><input data-labnote="${l[0]}" value="${state.labs[l[0]]?.note||''}"></td></tr>`).join('');renderBP();renderFood();document.getElementById('planRows').innerHTML=plan.map((p,i)=>`<div class="card" style="margin-bottom:9px"><div class="ey">${p[0]} · ${p[1]}</div><p>${p[2]}</p><label><input type="checkbox" data-plan="${i}" ${state.decisions['plan'+i]?'checked':''} style="width:auto"> Completed</label></div>`).join('');document.getElementById('decisions').innerHTML=['Medicines','Food chemistry','Exercise','Motor rehab','Gut-brain','Vitamin D / nutrients','Sleep / autonomic'].map(k=>`<div style="display:grid;grid-template-columns:1fr 170px;gap:8px;margin-bottom:8px"><span>${k}</span><select data-decision="${k}"><option>Not reviewed</option><option>KEEP</option><option>MODIFY</option><option>ESCALATE</option><option>REMOVE</option><option>INVESTIGATE</option></select></div>`).join('');hydrate();}
function addBP(){state.bp.push({});save(false);renderBP()}function renderBP(){document.getElementById('bpRows').innerHTML=state.bp.map((r,i)=>`<div class="row"><input type="datetime-local" data-bpdate="${i}" value="${r.date||''}"><input type="number" placeholder="SBP" data-sbp="${i}" value="${r.sbp||''}"><input type="number" placeholder="DBP" data-dbp="${i}" value="${r.dbp||''}"><input type="number" placeholder="HR" data-hr="${i}" value="${r.hr||''}"><button class="btn" onclick="state.bp.splice(${i},1);save(false);renderBP()">×</button></div>`).join('')||'<div class="muted small">No readings entered yet.</div>'}
function addFood(){state.foods.push({});save(false);renderFood()}function renderFood(){document.getElementById('foodRows').innerHTML=state.foods.map((r,i)=>`<div class="row"><select data-fday="${i}"><option>Day 1</option><option>Day 2</option><option>Day 3</option></select><input placeholder="Food / drink" data-fname="${i}" value="${r.name||''}"><input type="number" placeholder="grams / mL" data-fqty="${i}" value="${r.qty||''}"><input placeholder="meal / time" data-ftime="${i}" value="${r.time||''}"><button class="btn" onclick="state.foods.splice(${i},1);save(false);renderFood()">×</button></div>`).join('')||'<div class="muted small">No foods entered yet.</div>'}
function collect(){document.querySelectorAll('[data-lab]').forEach(e=>{let k=e.dataset.lab;state.labs[k]=state.labs[k]||{};state.labs[k].value=e.value});document.querySelectorAll('[data-labdate]').forEach(e=>{let k=e.dataset.labdate;state.labs[k]=state.labs[k]||{};state.labs[k].date=e.value});document.querySelectorAll('[data-labnote]').forEach(e=>{let k=e.dataset.labnote;state.labs[k]=state.labs[k]||{};state.labs[k].note=e.value});document.querySelectorAll('[data-med]').forEach(e=>state.notes['med'+e.dataset.med]=e.value);document.querySelectorAll('[data-bpdate]').forEach(e=>{let i=+e.dataset.bpdate;state.bp[i]=state.bp[i]||{};state.bp[i].date=e.value});document.querySelectorAll('[data-sbp]').forEach(e=>state.bp[+e.dataset.sbp].sbp=e.value);document.querySelectorAll('[data-dbp]').forEach(e=>state.bp[+e.dataset.dbp].dbp=e.value);document.querySelectorAll('[data-hr]').forEach(e=>state.bp[+e.dataset.hr].hr=e.value);document.querySelectorAll('[data-fname]').forEach(e=>state.foods[+e.dataset.fname].name=e.value);document.querySelectorAll('[data-fqty]').forEach(e=>state.foods[+e.dataset.fqty].qty=e.value);document.querySelectorAll('[data-ftime]').forEach(e=>state.foods[+e.dataset.ftime].time=e.value);document.querySelectorAll('[data-fday]').forEach(e=>state.foods[+e.dataset.fday].day=e.value);['recovery','questions','bodyNotes','symptoms','motorGoals','response'].forEach(id=>state.notes[id]=document.getElementById(id)?.value||'');['leftGrip','rightGrip','walk10','sts','leftArm','rightArm','leftLeg','rightLeg'].forEach(id=>state.motor[id]=document.getElementById(id)?.value||'');['bleeding','dizziness','fatigue','muscle'].forEach(id=>state.symptoms[id]=document.getElementById(id)?.value||'');document.querySelectorAll('[data-plan]').forEach(e=>state.decisions['plan'+e.dataset.plan]=e.checked);document.querySelectorAll('[data-decision]').forEach(e=>state.decisions[e.dataset.decision]=e.value)}
function save(show=true){collect();localStorage.setItem('ilmb_nilesh_live',JSON.stringify(state));if(show)alert('Saved on this device/browser.')}function saveAll(){save(true)}function exportData(){save(false);const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='Nilesh_ILMB_Data.json';a.click();URL.revokeObjectURL(a.href)}
function hydrate(){['recovery','questions','bodyNotes','symptoms','motorGoals','response'].forEach(id=>{let e=document.getElementById(id);if(e)e.value=state.notes[id]||''});['leftGrip','rightGrip','walk10','sts','leftArm','rightArm','leftLeg','rightLeg'].forEach(id=>{let e=document.getElementById(id);if(e)e.value=state.motor[id]||''});['bleeding','dizziness','fatigue','muscle'].forEach(id=>{let e=document.getElementById(id);if(e)e.value=state.symptoms[id]||'No'});document.querySelectorAll('[data-decision]').forEach(e=>{if(state.decisions[e.dataset.decision])e.value=state.decisions[e.dataset.decision]})}
const sys={brain:['Brain / right MCA','Known: right hemispheric ischemic injury with severe historical right-MCA disease.<br><br><span class="node">MCA flow</span> → <span class="node">O₂ / glucose delivery</span> → <span class="node">neural function</span> → <span class="node">motor / cognition</span><p class="muted small">Current lumen, collateral reserve and perfusion are still unquantified.</p>'],blood:['Platelets / thrombosis','<b>Clopidogrel:</b> ADP → P2Y12 → αIIbβ3 → aggregation.<br><br><b>Aspirin:</b> arachidonic acid → COX-1 → TXA₂ → aggregation.<p class="muted small">Both reduce pathological thrombosis and also reduce normal hemostatic capacity.</p>'],heart:['Heart / vessels','Tracked: blood pressure, resting HR, vascular stress and endothelial function.<br><br>vascular resistance + cardiac output → blood pressure'],liver:['Liver / lipids','Current key values: TG 301 mg/dL; ALT 81 U/L.<br><br>food/hepatic substrate → VLDL/TG production ⇄ clearance'],gut:['Gut–brain / gut–vascular axis','Food substrate → microbial metabolites → barrier / immune / vagal signals → metabolic / vascular / brain environment.<p class="muted small">Modifier pathway, not an antiplatelet substitute.</p>'],kidney:['Kidney / electrolytes','Creatinine 1.27 mg/dL, eGFR 72, potassium 5.3 mmol/L. This changes the safety boundary for diet, supplements and medicines.']};function openSys(k){document.getElementById('drawerBody').innerHTML=`<div class="ey">Explore my body</div><h2>${sys[k][0]}</h2><p>${sys[k][1]}</p>`;document.getElementById('drawer').classList.add('open')}function closeDrawer(){document.getElementById('drawer').classList.remove('open')}render();
</script></body></html>